def enforce_monotonicity(profiles):
    """Enforce delta(lower_bits) >= delta(higher_bits) via isotonic regression.
    Handles calibration noise where e.g. delta_4bit > delta_2bit.
    Returns a new profiles dict (original unchanged).
    """
    import copy
    enforced = copy.deepcopy(profiles)
    bit_order = [16, 8, 4, 2]  # high to low

    for l_str in enforced:
        for h_str in enforced[l_str]:
            qdata = enforced[l_str][h_str].get("quantization", {})
            if not qdata:
                continue
            # Collect deltas in descending bit order
            deltas = {}
            for b in bit_order:
                key = str(b)
                if key in qdata:
                    deltas[b] = qdata[key]
                elif b == 16:
                    deltas[16] = 0.0

            # Isotonic enforcement: scan from high to low bits
            # delta[b] = max(delta[b], delta[b_higher])
            prev = deltas.get(16, 0.0)
            for b in bit_order:
                if b not in deltas:
                    continue
                if deltas[b] < prev:
                    deltas[b] = prev
                prev = deltas[b]
                if b != 16:
                    qdata[str(b)] = deltas[b]

    return enforced
